    IF OLD.status<>'DRAFT' OR NEW.status<>'DRAFT' OR NEW.responsible_staff_id IS NULL THEN RAISE EXCEPTION 'Responsible change requires draft save and actual staff' USING ERRCODE='23514'; END IF;
  END IF;
