    OR (NEW.entity_type='SIZE_GROUP_MEMBER' AND (SELECT array_agg(k ORDER BY k) FROM jsonb_object_keys(evidence->'references') k) IS DISTINCT FROM ARRAY['size_group_id','size_id']) THEN
