 RETURNS trigger
 LANGUAGE plpgsql
 SET search_path TO 'pg_catalog', 'naijue_erp', 'pg_temp'
AS $function$
DECLARE kind text;
BEGIN
  IF TG_OP='UPDATE' THEN
    IF NEW.number IS DISTINCT FROM OLD.number THEN
      RAISE EXCEPTION 'A saved document number is immutable' USING ERRCODE='23514';
    END IF;
